+/**
+ * SVG Sanitization utility
+ * Removes potentially dangerous elements and attributes from SVG content
+ */
+
+const DANGEROUS_TAGS = ['script', 'foreignObject'];
+const DANGEROUS_ATTRS = [/^on/i, /^style$/i];
+const DANGEROUS_PROTOCOLS = ['javascript:', 'data:'];
+
+function sanitizeSvg(content) {
+  let sanitized = content;
+
+  // Remove script tags
+  DANGEROUS_TAGS.forEach(tag => {
+    const regex = new RegExp(`<${tag}[^>]*>[\\s\\S]*?</${tag}>`, 'gi');
+    sanitized = sanitized.replace(regex, '');
+    const selfClosingRegex = new RegExp(`<${tag}[^>]*\\/?>`, 'gi');
+    sanitized = sanitized.replace(selfClosingRegex, '');
+  });
+
+  // Remove dangerous attributes (event handlers like onclick, onerror, etc.)
+  DANGEROUS_ATTRS.forEach(attr => {
+    const regex = new RegExp(`${attr.source}=\\s*["'][^"']*["']`, 'gi');
+    sanitized = sanitized.replace(regex, '');
+  });
+
+  // Remove dangerous protocols from attributes
+  DANGEROUS_PROTOCOLS.forEach(protocol => {
+    const regex = new RegExp(`${protocol.replace(':', '\\:')}`, 'gi');
+    sanitized = sanitized.replace(regex, '');
+  });
+
+  return sanitized;
+}
+
+module.exports = { sanitizeSvg };
