/**
 * Shell metacharacters that could allow command injection.
 * These characters have special meaning in shells and could be
 * exploited for command injection attacks.
 */
const SHELL_METACHARACTERS = /[;&|`$()<>!\[的中]/.source;

function containsShellMetacharacters(input: string): boolean {
  return new RegExp(SHELL_METACHARACTERS).test(input);
}

/**
 * Execute a command in a Kubernetes pod or container using the Kubernetes client-node Exec API.
 * Returns the stdout output as a text response.
 * Throws McpError on failure.
 */
