+/**
+ * Password hashing utilities using bcryptjs
+ * bcryptjs truncates passwords at 72 bytes, so we enforce this limit
+ */
+
+const MAX_PASSWORD_LENGTH = 72;
+
+/**
+ * Hash a password using bcryptjs
+ * Truncates password to 72 bytes to prevent unexpected truncation
+ */
+export const hashPassword = async (password: string): Promise<string> => {
+  const { hash } = await import('bcryptjs');
+  
+  if (password.length > MAX_PASSWORD_LENGTH) {
+    console.warn(
+      `[Strapi] Password exceeds maximum length of ${MAX_PASSWORD_LENGTH} characters. ` +
+      `It will be truncated for hashing. Please use a shorter password.`
+    );
+    password = password.slice(0, MAX_PASSWORD_LENGTH);
+  }
+  
+  return hash(password, 10);
+};
+
+/**
+ * Validate that a password does not exceed the maximum allowed length
+ * @throws Error if password exceeds 72 characters
+ */
+export const validatePasswordLength = (password: string): void => {
+  if (password.length > MAX_PASSWORD_LENGTH) {
+    throw new Error(
+      `Password must not exceed ${MAX_PASSWORD_LENGTH} characters. ` +
+      `bcryptjs truncates passwords longer than ${MAX_PASSWORD_LENGTH} characters.`
+    );
+  }
+};
