@@ -0,0 +1,26 @@
+/**
+ * Validates and sanitizes a redirect URL to prevent open redirect attacks.
+ * Only allows:
+ * - Relative URLs starting with '/' (but not '//' to prevent protocol-relative attacks)
+ * - Same-origin absolute URLs
+ *
+ * @param url - The URL to validate
+ * @returns A safe redirect URL, or '/' as fallback
+ */
+export function isSafeRedirectUrl(url: string | null | undefined): string {
+  // Return default safe URL for empty/null/undefined values
+  if (!url) {
+    return '/';
+  }
+
+  // Allow relative paths starting with single '/' (not '//')
+  if (url.startsWith('/') && !url.startsWith('//')) {
+    return url;
+  }
+
+  // Allow same-origin absolute URLs
+  try {
+    const urlObj = new URL(url, window.location.origin);
+    if (urlObj.origin === window.location.origin) {
+      return url;
+    }
+  } catch {
+    // Invalid URL format - fall through to default
+  }
+
+  // Unsafe or external URL - return safe default
+  return '/';
+}

