+const dns = require('dns');
+const { promisify } = require('util');
+
+const lookupAsync = promisify(dns.lookup);
+
+// Reserved and private IPv4 ranges
+const PRIVATE_IP_PATTERNS = [
+  /^127\./,                      // Loopback
+  /^10\./,                       // Class A private
+  /^192\.168\./,                 // Class C private
+  /^172\.(1[6-9]|2[0-9]|3[0-1])\./, // Class B private
+  /^169\.254\./,                 // Link-local
+  /^0\./,                        // Current network
+  /^224\./,                      // Multicast
+  /^240\./,                      // Reserved
+  /^::1$/,                       // IPv6 loopback
+  /^fe80:/i,                     // IPv6 link-local
+  /^fc00:/i,                     // IPv6 unique local
+  /^fd00:/i,                     // IPv6 unique local
+];
+
+/**
+ * Check if an IP address is in a private/reserved range
+ * @param {string} ip - IP address to check
+ * @returns {boolean} - True if IP is private/reserved
+ */
+function isPrivateIP(ip) {
+  if (!ip) return true;
+  
+  // Handle IPv6 addresses
+  if (ip.includes(':')) {
+    for (const pattern of PRIVATE_IP_PATTERNS) {
+      if (pattern.test(ip)) {
+        return true;
+      }
+    }
+    return false;
+  }
+  
+  // Handle IPv4 addresses
+  for (const pattern of PRIVATE_IP_PATTERNS) {
+    if (pattern.test(ip)) {
+      return true;
+    }
+  }
+  
+  return false;
+}
+
+/**
+ * Validate a URL for SSRF vulnerabilities
+ * @param {string} url - URL to validate
+ * @returns {Promise<{valid: boolean, reason?: string}>}
+ */
+async function validateUrl(url) {
+  try {
+    const parsed = new URL(url);
+    
+    // Only allow HTTP and HTTPS protocols
+    if (!['http:', 'https:'].includes(parsed.protocol)) {
+      return { valid: false, reason: 'Only HTTP and HTTPS protocols are allowed' };
+    }
+    
+    // Check hostname
+    const hostname = parsed.hostname;
+    
+    // Block localhost variants
+    if (['localhost', '127.0.0.1', '::1', '0.0.0.0'].includes(hostname)) {
+      return { valid: false, reason: 'Localhost access is not allowed' };
+    }
+    
+    // Resolve DNS and check IP
+    const { address } = await lookupAsync(hostname);
+    
+    if (!address) {
+      return { valid: false, reason: 'Unable to resolve hostname' };
+    }
+    
+    if (isPrivateIP(address)) {
+      return { valid: false, reason: 'Access to private/internal networks is not allowed' };
+    }
+    
+    return { valid: true };
+  } catch (error) {
+    return { valid: false, reason: `Invalid URL: ${error.message}` };
+  }
+}
+
+/**
+ * Synchronous URL validation (basic checks only, no DNS lookup)
+ * @param {string} url - URL to validate
+ * @returns {{valid: boolean, reason?: string}}
+ */
+function validateUrlSync(url) {
+  try {
+    const parsed = new URL(url);
+    
+    if (!['http:', 'https:'].includes(parsed.protocol)) {
+      return { valid: false, reason: 'Only HTTP and HTTPS protocols are allowed' };
+    }
+    
+    const hostname = parsed.hostname;
+    
+    if (['localhost', '127.0.0.1', '::1', '0.0.0.0'].includes(hostname)) {
+      return { valid: false, reason: 'Localhost access is not allowed' };
+    }
+    
+    return { valid: true };
+  } catch (error) {
+    return { valid: false, reason: `Invalid URL: ${error.message}` };
+  }
+}
+
+module.exports = {
+  validateUrl,
+  validateUrlSync,
+  isPrivateIP
+};
