+/**
+ * Converts credentials object to a string representation for logging.
+ * Sensitive fields (accessKeyId, secretAccessKey, sessionToken) are redacted.
+ * The expiration field is also redacted as its presence indicates temporary credentials
+ * which should not be exposed.
+ */
+export function credentialsToString(credentials: AWS.Credentials | AWS.Credentials & { expiration?: Date }): string {
+  const hasCredentials = credentials &&
+    (credentials.accessKeyId || credentials.secretAccessKey || credentials.sessionToken);
+  
+  if (!hasCredentials) {
+    return '[not provided]';
+  }
+
+  const hasExpiration = 'expiration' in credentials && credentials.expiration;
+  if (hasExpiration) {
+    return `[temporary credentials with expiration: ${credentials.expiration.toISOString()}]`;
+  }
+
+  return '[credentials with sensitive data - not logged]';
+}

