--- /dev/null
+++ b/api/src/utils/strip-html.ts
@@ -0,0 +1,15 @@
+/**
+ * Strip HTML tags from a string to prevent HTML injection attacks.
+ * This is used to sanitize user-provided content like comments.
+ */
+export function stripHtml(input: string | null | undefined): string {
+	if (!input) {
+		return '';
+	}
+
+	// Remove all HTML tags by replacing tag content with empty string
+	const stripped = input.replace(/<[^>]*>/g, '');
+
+	// Trim whitespace and return
+	return stripped.trim();
+}

