+/**
+ * Check if a URL is internal (same origin as the current page)
+ * or points to a known trusted endpoint
+ */
+export const isInternalURL = (url: string): boolean => {
+  if (!url) return true;
+
+  try {
+    const currentOrigin = window.location.origin;
+    const urlOrigin = new URL(url, window.location.origin).origin;
+    return currentOrigin === urlOrigin;
+  } catch {
+    return false;
+  }
+};
