+// Utility functions for sanitizing user input to prevent XSS attacks
+
+/**
+ * Sanitizes a URL to prevent XSS attacks via javascript: or data: protocols
+ * @param url - The URL to sanitize
+ * @returns A safe URL that cannot be used for XSS attacks
+ */
+export function sanitizeUrl(url: string): string {
+	if (!url) return '';
+
+	// Block dangerous protocols (javascript:, data:, vbscript:, etc.)
+	const dangerousProtocols = /^\s*(javascript|vbscript|data):/i;
+	if (dangerousProtocols.test(url)) {
+		return '#';
+	}
+
+	// Also check for expressions and other potential XSS vectors
+	const dangerousPatterns = [/\bon\w+\s*=/i, /<\s*\//i, /javascript\s*:/i];
+	for (const pattern of dangerousPatterns) {
+		if (pattern.test(url)) {
+			return '#';
+		}
+	}
+
+	return url;
+}

