new file mode 100644
index 0000000..1234567
--- /dev/null
+++ b/packages/cli/src/utils/validatePath.ts
@@ -0,0 +1,18 @@
+import path from 'path';
+
+/**
+ * Validates that a user-provided path resolves to within the allowed base directory.
+ * This prevents path traversal attacks (CWE-22).
+ *
+ * @param userPath - The path provided by the user
+ * @param basePath - The base directory that the user path must be within
+ * @returns The resolved and validated absolute path
+ * @throws Error if the path would escape the base directory
+ */
+export function validatePath(userPath: string, basePath: string): string {
+	const resolvedPath = path.resolve(basePath, userPath);
+	const normalizedPath = path.normalize(resolvedPath);
+
+	if (!normalizedPath.startsWith(path.resolve(basePath) + path.sep) && normalizedPath !== path.resolve(basePath)) {
+		throw new Error(`Invalid path: ${userPath} escapes base directory`);
+	}
+
+	return normalizedPath;
+}

