+import { Crypto } from '@builder.io/qwik';
+
+const CSRF_COOKIE_NAME = 'q_csrf';
+const CSRF_HEADER_NAME = 'x-csrf-token';
+const CSRF_TOKEN_LENGTH = 32;
+
+/**
+ * Generate a cryptographically secure CSRF token
+ */
+export function generateCsrfToken(): string {
+  const array = new Uint8Array(CSRF_TOKEN_LENGTH);
+  crypto.getRandomValues(array);
+  return Array.from(array, (byte) => byte.toString(16).padStart(2, '0')).join('');
+}
+
+/**
+ * Set CSRF cookie on response
+ */
+export function setCsrfCookie(cookie: Map<string, string>): void {
+  cookie.set(CSRF_COOKIE_NAME, generateCsrfToken());
+}
+
+/**
+ * Validate CSRF token from request
+ */
+export function validateCsrfToken(
+  cookie: Map<string, string>,
+  body: Record<string, any> | FormData | null,
+  requestToken: string | null
+): boolean {
+  const cookieToken = cookie.get(CSRF_COOKIE_NAME);
+
+  if (!cookieToken) {
+    return false;
+  }
+
+  // Token can be in body as _csrf or in the x-csrf-token header
+  const bodyToken = body instanceof FormData ? body.get('_csrf') : body?._csrf;
+  const token = requestToken || bodyToken;
+
+  return token === cookieToken;
+}
+
+export { CSRF_HEADER_NAME, CSRF_COOKIE_NAME };
