+    "ondragover", "ondragstart", "ondrop", "oncanplay", "oncanplaythrough", "oncuechange"
+];
+
+export const sanitizeXSS = (html: string): string => {
+    // Remove dangerous tags
+    let sanitized = html;
+    DANGEROUS_TAGS.forEach((tag) => {
+        const regex = new RegExp(`<${tag}[^>]*>[\\s\\S]*?<\\/${tag}>`, "gi");
+        sanitized = sanitized.replace(regex, "");
