+/**
+ * Sanitizes a string for safe inclusion in LLM prompts.
+ * Removes control characters, format characters, and zero-width characters
+ * that could be used for prompt injection attacks.
+ */
+function sanitizePromptValue(str) {
+  if (typeof str !== 'string') {
+    return '';
+  }
+  return str
+    // Remove C0 control characters (U+0000 to U+001F) and DEL (U+007F)
+    .replace(/[\u0000-\u001F\u007F]/g, '')
+    // Remove C1 control characters (U+0080 to U+009F)
+    .replace(/[\u0080-\u009F]/g, '')
+    // Replace line separator (U+2028) and paragraph separator (U+2029)
+    .replace(/[\u2028\u2029]/g, '')
+    // Remove zero-width characters (zero-width space, BOM, etc.)
+    .replace(/[\u200B-\u200D\uFEFF]/g, '');
+}
+
+module.exports = { sanitizePromptValue };
