+/**
+ * Image optimization utilities for Cloudflare adapter.
+ * This module handles secure image URL generation with hash validation
+ * to prevent SSRF attacks.
+ */
+
+const ALLOWED_IMAGE_HOSTS = [
+  "images.unsplash.com",
+  "res.cloudinary.com",
+  "picsum.photos",
+  "placekitten.com",
+];
+
+/**
+ * Validates that a URL points to an allowed image host.
+ * This prevents SSRF attacks by ensuring only pre-approved domains
+ * can be proxied through the image optimization endpoint.
+ */
+function isUrlFromAllowedHost(url: URL): boolean {
+  const hostname = url.hostname.toLowerCase();
+  return ALLOWED_IMAGE_HOSTS.some(
+    (allowed) => hostname === allowed || hostname.endsWith(`.${allowed}`)
+  );
+}
+
+/**
+ * Generates a hash for an image URL for secure caching.
+ * Uses a simple hash based on the normalized URL.
+ */
+function generateHashForUrl(url: string): string {
+  // Simple hash function for URL identification
+  let hash = 0;
+  for (let i = 0; i < url.length; i++) {
+    const char = url.charCodeAt(i);
+    hash = ((hash << 5) - hash) + char;
+    hash = hash & hash; // Convert to 32bit integer
+  }
+  return Math.abs(hash).toString(36);
+}
+
+/**
+ * Resolves an image hash to its original URL.
+ * Returns null if the hash is invalid or the URL is not from an allowed host.
+ */
+export async function imageHashToUrl(
+  hash: string,
+  requestUrl: URL
+): Promise<string | null> {
+  // In a real implementation, this would look up the hash in a KV store
+  // For now, we reject all external URLs to prevent SSRF
+  // until a proper hash-to-URL mapping is implemented
+
+  // Block all external URLs to prevent SSRF
+  // The image optimization feature requires a secure hash mapping
+  // which should be implemented by the deployment system
+  return null;
+}
+
+/**
+ * Converts an image URL to a hash for caching purposes.
+ * Only URLs from allowed hosts can be converted to hashes.
+ */
+export async function urlToImageHash(url: string): Promise<string | null> {
+  try {
+    const parsedUrl = new URL(url);
+
+    if (!isUrlFromAllowedHost(parsedUrl)) {
+      return null;
+    }
+
+    return generateHashForUrl(url);
+  } catch {
+    return null;
+  }
+}

