+++ b/packages/plate-media/src/utils/sanitizeUrl.ts
@@ -0,0 +1,28 @@
+/**
+ * Sanitizes a URL to prevent XSS attacks.
+ * Removes dangerous protocols like javascript:, data:, vbscript:, etc.
+ */
+export const sanitizeUrl = (url: string | undefined): string | undefined => {
+  if (!url) return undefined;
+
+  const trimmedUrl = url.trim().toLowerCase();
+
+  // List of dangerous protocols that can lead to XSS
+  const dangerousProtocols = [
+    'javascript:',
+    'data:',
+    'vbscript:',
+    'vbscript\0:', // some parsers add null byte
+  ];
+
+  for (const protocol of dangerousProtocols) {
+    if (trimmedUrl.startsWith(protocol)) {
+      return undefined;
+    }
+  }
+
+  return url;
+};
+
+export default sanitizeUrl;
