+  /;/g,
+  /\|/g,
+  /`/g,
+  /\$/g,
+  /\$/g,
+  /\(\)/g,
+  /\$\{/g,
+  /\$\(/g,
+  /\n/g,
+  /\r/g,
+];
+
+/**
+ * Validates that a string does not contain potentially dangerous
