+const path = require('path');
+
+/**
+ * Check if a target path is within a given directory.
+ * This prevents directory traversal attacks by ensuring
+ * the canonical path stays within the expected boundary.
+ *
+ * @param {string} targetPath - The path to check
+ * @param {string} directory - The base directory
+ * @returns {boolean} - True if targetPath is within directory
+ */
+function isWithinDirectory(targetPath, directory) {
+    const canonicalDir = path.resolve(directory);
+    const canonicalTarget = path.resolve(targetPath);
+    return canonicalTarget.startsWith(canonicalDir + path.sep) ||
+           canonicalTarget === canonicalDir;
+}
+
+module.exports = { isWithinDirectory };

