@@ -0,0 +1,47 @@
+/**
+ * DNS Rebinding Protection Middleware
+ * 
+ * Prevents DNS rebinding attacks by validating the Host header
+ * against an allowed list of trusted hosts.
+ */
+
+const ALLOWED_HOSTS = (process.env.ALLOWED_HOSTS || 'localhost,127.0.0.1,::1')
+    .split(',')
+    .map(h => h.trim().toLowerCase());
+
+const ALLOWED_SCHEMES = ['http:', 'https:'];
+
+/**
+ * Extracts the host portion from a URL string
+ * @param {string} url 
+ * @returns {string|null}
+ */
+function extractHost(url) {
+    try {
+        const parsed = new URL(url);
+        return parsed.hostname.toLowerCase();
+    } catch {
+        return null;
+    }
+}
+
+/**
+ * Checks if the given host is in the allowed list
+ * @param {string} host 
+ * @returns {boolean}
+ */
+function isHostAllowed(host) {
+    if (!host) return false;
+    
+    const normalizedHost = host.split(':')[0].toLowerCase();
+    
+    // Check exact match
+    if (ALLOWED_HOSTS.includes(normalizedHost)) {
+        return true;
+    }
+    
+    // Check if host matches any allowed pattern
+    return ALLOWED_HOSTS.some(allowed => {
+        if (allowed.startsWith('.')) {
+            // subdomain wildcard (e.g., ".example.com")
+            return normalizedHost.endsWith(allowed) || normalizedHost === allowed.slice(1);
+        }
+        return false;
+    });
+}
+
+module.exports = function dnsRebindProtection(req, res, next) {
+    const host = req.get('host') || req.get('Host');
+    
+    if (!isHostAllowed(host)) {
+        console.warn(`DNS rebinding protection: blocked request with host "${host}"`);
+        return res.status(403).json({ error: 'Forbidden: Invalid or unauthorized host' });
+    }
+    
+    next();
+};

